CREATE TABLE public.pm_task_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES public.pm_tasks(id), project_id uuid NOT NULL REFERENCES public.pm_projects(id), author_id uuid NOT NULL REFERENCES public.profiles(id), recipient_id uuid REFERENCES public.profiles(id), kind text NOT NULL CHECK(kind IN ('question','answer','mention')), reply_to_id uuid REFERENCES public.pm_task_messages(id), text text NOT NULL CHECK(length(trim(text)) BETWEEN 1 AND 4000), seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.pm_task_messages TO authenticated; GRANT ALL ON public.pm_task_messages TO service_role;
ALTER TABLE public.pm_task_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY pm_messages_read ON public.pm_task_messages FOR SELECT TO authenticated USING(public.pm_can_edit(project_id));
CREATE POLICY pm_messages_insert ON public.pm_task_messages FOR INSERT TO authenticated WITH CHECK(public.pm_can_edit(project_id) AND author_id=auth.uid());
CREATE POLICY pm_messages_seen ON public.pm_task_messages FOR UPDATE TO authenticated USING(public.pm_can_edit(project_id) AND recipient_id=auth.uid() AND kind='mention') WITH CHECK(public.pm_can_edit(project_id) AND recipient_id=auth.uid() AND kind='mention');
CREATE UNIQUE INDEX pm_one_answer ON public.pm_task_messages(reply_to_id) WHERE kind='answer';
CREATE INDEX pm_message_task ON public.pm_task_messages(task_id,created_at);
CREATE FUNCTION public.pm_message_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE q public.pm_task_messages; p uuid; BEGIN
 IF TG_OP='UPDATE' THEN IF NEW.id<>OLD.id OR NEW.task_id<>OLD.task_id OR NEW.project_id<>OLD.project_id OR NEW.author_id<>OLD.author_id OR NEW.recipient_id IS DISTINCT FROM OLD.recipient_id OR NEW.kind<>OLD.kind OR NEW.reply_to_id IS DISTINCT FROM OLD.reply_to_id OR NEW.text<>OLD.text OR NEW.created_at<>OLD.created_at OR OLD.kind<>'mention' OR OLD.recipient_id<>auth.uid() OR NEW.seen_at IS NULL THEN RAISE EXCEPTION 'O histórico da conversa é imutável.'; END IF; NEW.seen_at:=COALESCE(OLD.seen_at,now()); RETURN NEW; END IF;
 SELECT project_id INTO p FROM public.pm_tasks WHERE id=NEW.task_id;
 IF p IS NULL OR p<>NEW.project_id OR NOT public.pm_can_edit(p) OR NEW.author_id<>auth.uid() OR NEW.seen_at IS NOT NULL THEN RAISE EXCEPTION 'Tarefa ou autor inválido.'; END IF;
 NEW.created_at:=now();
 IF NEW.kind='answer' THEN SELECT * INTO q FROM public.pm_task_messages WHERE id=NEW.reply_to_id FOR UPDATE;
 IF q.id IS NULL OR q.kind<>'question' OR q.task_id<>NEW.task_id OR q.recipient_id<>auth.uid() OR q.author_id=auth.uid() OR EXISTS(SELECT 1 FROM public.pm_task_messages WHERE reply_to_id=q.id) THEN RAISE EXCEPTION 'Somente o destinatário pode responder uma pergunta pendente desta tarefa.'; END IF; NEW.recipient_id:=q.author_id;
 ELSE IF NEW.reply_to_id IS NOT NULL OR NEW.recipient_id IS NULL OR NEW.recipient_id=auth.uid() OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.recipient_id AND is_active AND deleted_at IS NULL) OR NOT private.has_app_access(NEW.recipient_id,'projects') OR (NOT EXISTS(SELECT 1 FROM public.pm_projects WHERE id=p AND manager_id=NEW.recipient_id) AND NOT EXISTS(SELECT 1 FROM public.pm_members WHERE project_id=p AND user_id=NEW.recipient_id)) THEN RAISE EXCEPTION 'Selecione outro participante autorizado do projeto.'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.pm_message_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER pm_messages_guard BEFORE INSERT OR UPDATE ON public.pm_task_messages FOR EACH ROW EXECUTE FUNCTION public.pm_message_guard();
CREATE TRIGGER pm_messages_audit AFTER INSERT OR UPDATE ON public.pm_task_messages FOR EACH ROW EXECUTE FUNCTION public.pm_audit_row();
CREATE FUNCTION public.pm_pending_messages() RETURNS TABLE(message_id uuid,project_id uuid,task_id uuid,project_name text,task_name text,text text,kind text,created_at timestamptz) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT m.id,m.project_id,m.task_id,p.name,t.name,m.text,m.kind,m.created_at FROM public.pm_task_messages m JOIN public.pm_tasks t ON t.id=m.task_id JOIN public.pm_projects p ON p.id=m.project_id WHERE m.recipient_id=auth.uid() AND ((m.kind='question' AND NOT EXISTS(SELECT 1 FROM public.pm_task_messages a WHERE a.reply_to_id=m.id AND a.kind='answer')) OR (m.kind='mention' AND m.seen_at IS NULL)) ORDER BY m.created_at $$;
REVOKE ALL ON FUNCTION public.pm_pending_messages() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pm_pending_messages() TO authenticated;
CREATE TABLE public.pm_task_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES public.pm_tasks(id),project_id uuid NOT NULL REFERENCES public.pm_projects(id),uploaded_by uuid NOT NULL REFERENCES public.profiles(id),file_name text NOT NULL CHECK(length(file_name) BETWEEN 1 AND 255),storage_path text NOT NULL UNIQUE,content_type text NOT NULL,file_size bigint NOT NULL CHECK(file_size>0),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.pm_task_attachments TO authenticated; GRANT ALL ON public.pm_task_attachments TO service_role;
ALTER TABLE public.pm_task_attachments ENABLE ROW LEVEL SECURITY;
CREATE POLICY pm_files_read ON public.pm_task_attachments FOR SELECT TO authenticated USING(public.pm_can_edit(project_id));
CREATE POLICY pm_files_insert ON public.pm_task_attachments FOR INSERT TO authenticated WITH CHECK(public.pm_can_edit(project_id) AND uploaded_by=auth.uid() AND EXISTS(SELECT 1 FROM public.pm_tasks t WHERE t.id=task_id AND t.project_id=pm_task_attachments.project_id) AND split_part(storage_path,'/',1)=auth.uid()::text AND split_part(storage_path,'/',2)=task_id::text);
CREATE TRIGGER pm_files_audit AFTER INSERT ON public.pm_task_attachments FOR EACH ROW EXECUTE FUNCTION public.pm_audit_row();
CREATE POLICY pm_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='projects-attachments' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.pm_tasks t WHERE t.id::text=(storage.foldername(name))[2] AND public.pm_can_edit(t.project_id)));
CREATE POLICY pm_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='projects-attachments' AND EXISTS(SELECT 1 FROM public.pm_tasks t WHERE t.id::text=(storage.foldername(name))[2] AND public.pm_can_edit(t.project_id)));
CREATE POLICY pm_storage_cleanup ON storage.objects FOR DELETE TO authenticated USING(bucket_id='projects-attachments' AND (storage.foldername(name))[1]=auth.uid()::text AND NOT EXISTS(SELECT 1 FROM public.pm_task_attachments a WHERE a.storage_path=name));